statement.sql:
ALTER TABLE task_parameters ADD COLUMN IF NOT EXISTS position integer;
ALTER TABLE task_parameters ADD COLUMN IF NOT EXISTS source_type varchar(16) NOT NULL DEFAULT 'fixed';
ALTER TABLE task_parameters ADD COLUMN IF NOT EXISTS rest_source jsonb;
ALTER TABLE task_parameters ALTER COLUMN value DROP NOT NULL;
WITH ordered AS (
 SELECT id, row_number() OVER (PARTITION BY task_id ORDER BY id)::integer AS position
 FROM task_parameters
) UPDATE task_parameters p SET position=o.position FROM ordered o
WHERE p.id=o.id AND p.position IS NULL;
ALTER TABLE task_parameters ALTER COLUMN position SET NOT NULL;
ALTER TABLE task_requests ADD COLUMN IF NOT EXISTS phase varchar(16) NOT NULL DEFAULT 'steps';
ALTER TABLE task_requests ADD COLUMN IF NOT EXISTS run_parameter_id integer;
ALTER TABLE task_requests ALTER COLUMN run_step_id DROP NOT NULL;
ALTER TABLE task_requests ALTER COLUMN step_id DROP NOT NULL;
